package l; import org.springframework.web.reactive.function.client.WebClient; import reactor.core.publisher.Mono; @org.springframework.stereotype.Component @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="card.on", havingValue="true") public class CardPay implements Pay { public Mono<String> pay() { return WebClient.create("http://svc-b").get().uri("/b/card").retrieve().bodyToMono(String.class); } }
